"""Generated by the QA agent for STORY-001: Open an account and check its balance."""


def test_tc_001_01_open_account_with_initial_deposit(api):
    """TC-001-01"""
    r = api.post("/accounts", json={"owner": "Amira Hassan", "initial_deposit": 100})
    assert r.status_code == 201, r.text
    body = r.json()
    assert body["id"].startswith("ACC-")
    assert body["owner"] == "Amira Hassan"
    assert body["balance"] == 100


def test_tc_001_02_look_up_existing_account(api):
    """TC-001-02"""
    acc = api.create_account("Omar Farouk", 250)
    r = api.get(f"/accounts/{acc['id']}")
    assert r.status_code == 200, r.text
    assert r.json()["balance"] == 250


def test_tc_001_03_blank_owner_rejected(api):
    """TC-001-03"""
    r = api.post("/accounts", json={"owner": "   ", "initial_deposit": 10})
    assert r.status_code == 422, r.text


def test_tc_001_04_negative_initial_deposit_rejected(api):
    """TC-001-04"""
    r = api.post("/accounts", json={"owner": "Omar", "initial_deposit": -50})
    assert r.status_code == 422, r.text


def test_tc_001_05_unknown_account_returns_404(api):
    """TC-001-05"""
    r = api.get("/accounts/ACC-9999")
    assert r.status_code == 404, r.text
